{
  "name": "js-no-var",
  "intent": "Block `var` declarations — function-scoped, hoisted, easy to misuse.",
  "severity": "error",
  "hooks": [
    "pre-commit",
    "pre-tool"
  ],
  "enabled": true,
  "checks": [
    {
      "id": "js-no-var-pattern",
      "type": "pattern",
      "config": {
        "pattern": "(^|[^A-Za-z0-9_])var\\s+[A-Za-z_$]"
      },
      "severity": "block",
      "message": "Use `let` (mutable) or `const` (immutable) instead of `var`."
    },
    {
      "id": "js-no-var-guidance",
      "type": "agent",
      "config": {
        "prompt": "RULE: Never write `var`. Use `const` for values that don't change after assignment, `let` for ones that do."
      },
      "severity": "block",
      "message": "Use `let` (mutable) or `const` (immutable) instead of `var`."
    }
  ]
}

{
  "name": "no-debugger",
  "intent": "Block `debugger;` statements from being committed.",
  "severity": "error",
  "hooks": [
    "pre-commit",
    "pre-tool"
  ],
  "enabled": true,
  "checks": [
    {
      "id": "no-debugger-pattern",
      "type": "pattern",
      "config": {
        "pattern": "\\bdebugger\\b\\s*;"
      },
      "severity": "block",
      "message": "Remove debugger statements before committing — they freeze the page in prod when devtools are open."
    },
    {
      "id": "no-debugger-guidance",
      "type": "agent",
      "config": {
        "prompt": "RULE: Never commit `debugger;` statements. Use logger.debug() for persistent diagnostics."
      },
      "severity": "block",
      "message": "Remove debugger statements before committing — they freeze the page in prod when devtools are open."
    }
  ]
}

{
  "name": "no-document-write",
  "intent": "Block document.write() — blocks parser, breaks async pages, security footgun.",
  "severity": "error",
  "hooks": [
    "pre-commit",
    "pre-tool"
  ],
  "enabled": true,
  "checks": [
    {
      "id": "no-document-write-pattern",
      "type": "pattern",
      "config": {
        "pattern": "\\bdocument\\.write(?:ln)?\\s*\\("
      },
      "severity": "block",
      "message": "document.write() blocks the parser and is unsafe with user-supplied content. Use DOM APIs."
    },
    {
      "id": "no-document-write-guidance",
      "type": "agent",
      "config": {
        "prompt": "RULE: Never call document.write() or document.writeln(). Use DOM APIs (createElement / appendChild) or framework rendering."
      },
      "severity": "block",
      "message": "document.write() blocks the parser and is unsafe with user-supplied content. Use DOM APIs."
    }
  ]
}

{
  "name": "no-double-equals",
  "intent": "Require strict equality (=== / !==) instead of == / !=.",
  "severity": "error",
  "hooks": [
    "pre-commit",
    "pre-tool"
  ],
  "enabled": true,
  "checks": [
    {
      "id": "no-double-equals-pattern",
      "type": "pattern",
      "config": {
        "pattern": "([^=!])(==|!=)([^=])"
      },
      "severity": "block",
      "message": "Use === / !== for strict equality. == coerces types and causes surprises."
    },
    {
      "id": "no-double-equals-guidance",
      "type": "agent",
      "config": {
        "prompt": "RULE: Never use == or != in JS/TS. Always use === / !==. Loose equality coerces types in non-obvious ways."
      },
      "severity": "block",
      "message": "Use === / !== for strict equality. == coerces types and causes surprises."
    }
  ]
}

{
  "name": "no-eval-call",
  "intent": "Block eval() — arbitrary code execution risk.",
  "severity": "error",
  "hooks": [
    "pre-commit",
    "pre-tool"
  ],
  "enabled": true,
  "checks": [
    {
      "id": "no-eval-call-pattern",
      "type": "pattern",
      "config": {
        "pattern": "\\beval\\s*\\("
      },
      "severity": "block",
      "message": "eval() runs arbitrary code with the caller's scope. Don't use it."
    },
    {
      "id": "no-eval-call-guidance",
      "type": "agent",
      "config": {
        "prompt": "RULE: Never call eval(). It's a top vector for code injection. Use JSON.parse for data, function references for dispatch, dynamic imports for code-splitting."
      },
      "severity": "block",
      "message": "eval() runs arbitrary code with the caller's scope. Don't use it."
    }
  ]
}

{
  "name": "ts-no-any",
  "intent": "Block `: any` and `as any` in TypeScript — defeats the type system.",
  "severity": "error",
  "hooks": [
    "pre-commit",
    "pre-tool"
  ],
  "enabled": true,
  "checks": [
    {
      "id": "ts-no-any-pattern",
      "type": "pattern",
      "config": {
        "pattern": "(:\\s*any\\b|\\bas\\s+any\\b)"
      },
      "severity": "block",
      "message": "TypeScript `any` defeats type checking — use a real type or `unknown`."
    },
    {
      "id": "ts-no-any-guidance",
      "type": "agent",
      "config": {
        "prompt": "RULE: Never use `any` in TypeScript. Use a concrete type, `unknown`, or generic constraints. If the shape is unknown at the boundary, use `unknown` and narrow with type guards."
      },
      "severity": "block",
      "message": "TypeScript `any` defeats type checking — use a real type or `unknown`."
    }
  ]
}
